import { model, models, Schema, type InferSchemaType, type Model } from "mongoose";
import type { Item as ApiItem } from "@recall/shared";

const userSchema = new Schema(
  {
    email: { type: String, required: true, unique: true, lowercase: true, trim: true },
    passwordHash: { type: String, required: true },
  },
  { timestamps: true },
);

const itemSchema = new Schema({
  userId: { type: Schema.Types.ObjectId, ref: "User", required: true },
  /** UUID generated by whichever client created the item. Makes sync idempotent. */
  clientId: { type: String, required: true },
  kind: { type: String, enum: ["link", "note"], required: true },
  content: { type: String, required: true },
  url: { type: String, default: null },
  title: { type: String, default: null },
  summary: { type: String, default: null },
  tags: { type: [String], default: [] },
  aiStatus: { type: String, enum: ["pending", "done", "failed", "skipped"], default: "pending" },
  /** Timestamps from the client. clientUpdatedAt decides last-write-wins conflicts. */
  clientCreatedAt: { type: Date, required: true },
  clientUpdatedAt: { type: Date, required: true },
  /** Soft delete, so deletions can sync to other devices as tombstones. */
  deletedAt: { type: Date, default: null },
  /** Server clock: when this document last changed. Incremental pulls query on this. */
  syncedAt: { type: Date, required: true },
});

itemSchema.index({ userId: 1, clientId: 1 }, { unique: true });
itemSchema.index({ userId: 1, syncedAt: 1 });
itemSchema.index({ userId: 1, deletedAt: 1, clientCreatedAt: -1 });
itemSchema.index({ userId: 1, tags: 1 });

export type UserDoc = InferSchemaType<typeof userSchema>;
export type ItemDoc = InferSchemaType<typeof itemSchema>;

export const User: Model<UserDoc> = (models.User as Model<UserDoc>) ?? model("User", userSchema);
export const Item: Model<ItemDoc> = (models.Item as Model<ItemDoc>) ?? model("Item", itemSchema);

type ItemLike = {
  clientId: string;
  kind: string;
  content: string;
  url?: string | null;
  title?: string | null;
  summary?: string | null;
  tags?: string[] | null;
  aiStatus?: string | null;
  clientCreatedAt: Date;
  clientUpdatedAt: Date;
  deletedAt?: Date | null;
};

/** Database document → API shape shared with the clients. */
export function toApiItem(doc: ItemLike): ApiItem {
  return {
    id: doc.clientId,
    kind: doc.kind as ApiItem["kind"],
    content: doc.content,
    url: doc.url ?? null,
    title: doc.title ?? null,
    summary: doc.summary ?? null,
    tags: [...(doc.tags ?? [])],
    aiStatus: (doc.aiStatus ?? "pending") as ApiItem["aiStatus"],
    createdAt: doc.clientCreatedAt.toISOString(),
    updatedAt: doc.clientUpdatedAt.toISOString(),
    deletedAt: doc.deletedAt ? doc.deletedAt.toISOString() : null,
  };
}
